import Image from "next/image";
import Link from "next/link";

export default function Hero() {
  return (
    <section className="relative min-h-[660px] overflow-hidden border-b border-[#DED5C7] bg-[#F8F4EC]">
      {/* Map background */}
      <div
        className="absolute inset-0 bg-cover bg-center opacity-[0.38]"
        style={{
          backgroundImage:
            "url('/images/brand/fio-map-background.png')",
        }}
      />

      {/* Soft cream overlay */}
      <div className="absolute inset-0 bg-[#F8F4EC]/45" />

      {/* Faint compass on left */}
      <div className="pointer-events-none absolute -left-28 top-16 hidden h-[430px] w-[430px] rounded-full border border-[#B98A3D]/10 lg:block">
        <div className="absolute inset-14 rounded-full border border-[#B98A3D]/10" />
        <div className="absolute left-1/2 top-0 h-full w-px bg-[#B98A3D]/10" />
        <div className="absolute left-0 top-1/2 h-px w-full bg-[#B98A3D]/10" />
      </div>

      {/* Winding dotted path */}
      <svg
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 h-full w-full opacity-50"
        viewBox="0 0 1600 760"
        preserveAspectRatio="none"
      >
        <path
          d="M40 170 C190 120, 280 210, 180 285 C90 350, 145 440, 250 405"
          fill="none"
          stroke="#C89D4A"
          strokeWidth="2.5"
          strokeDasharray="4 10"
          strokeLinecap="round"
        />

        <path
          d="M1290 65 C1450 80, 1510 170, 1380 225 C1260 280, 1310 350, 1540 370"
          fill="none"
          stroke="#C89D4A"
          strokeWidth="2.5"
          strokeDasharray="4 10"
          strokeLinecap="round"
        />
      </svg>

      {/* Hero content */}
      <div className="relative mx-auto flex min-h-[660px] max-w-6xl flex-col items-center justify-center px-6 pb-12 pt-10 text-center">
        <Image
          src="/images/brand/fio-logo.png"
          alt="Figuring It Out compass, hourglass, book, leaves, and path logo"
          width={350}
          height={350}
          priority
          className="h-auto w-[230px] sm:w-[270px] lg:w-[310px]"
        />

        <h1 className="mt-2 font-serif text-[2.85rem] leading-none tracking-[0.055em] text-[#173E2C] sm:text-6xl lg:text-[4.35rem]">
          FIGURING IT OUT
          <sup className="ml-1 align-super text-[11px] tracking-normal">™</sup>
        </h1>

        <div className="my-5 flex items-center justify-center gap-3">
          <span className="h-px w-20 bg-[#C89D4A]" />
          <span className="h-2.5 w-2.5 rotate-45 bg-[#C89D4A]" />
          <span className="h-px w-20 bg-[#C89D4A]" />
        </div>

        <h2 className="font-serif text-[1.9rem] leading-tight text-[#173E2C] sm:text-4xl lg:text-[2.65rem]">
          Choosing to keep moving
          <span className="mt-1 block italic text-[#A86F24]">
            when life doesn&apos;t make sense.
          </span>
        </h2>

        <p className="mt-5 font-serif text-xl text-[#29372F] sm:text-2xl">
          One philosophy. Two paths.
        </p>

        <Link
          href="#choose-your-path"
          className="mt-7 inline-flex items-center gap-4 rounded-[3px] bg-[#173E2C] px-8 py-4 text-[11px] font-semibold uppercase tracking-[0.19em] text-white shadow-md transition hover:bg-[#5A2346]"
        >
          Begin Your Journey
          <span className="text-[#D4A64F]" aria-hidden="true">
            ✦
          </span>
        </Link>
      </div>
    </section>
  );
}